    // ========================================================

    public void refresh()
    {
        listPanel.removeAll();

        List<ActiveFlipStore.ActiveFlip> flips =
                store.getAll();

        int activeCount =
                0;

        for (
                ActiveFlipStore.ActiveFlip flip
                : flips
        )
        {
            if (
                    flip == null
                            || flip.isCompleted()
            )
            {
                continue;
            }

            activeCount++;

            listPanel.add(
                    createFlipCard(
                            flip
                    )
            );

            listPanel.add(
                    Box.createVerticalStrut(
                            8
                    )
            );
        }

        countLabel.setText(
                activeCount
                        + (
                        activeCount == 1
                                ? " active flip"
                                : " active flips"
                )
        );

        if (activeCount == 0)
        {
            listPanel.add(
                    createEmptyState()
            );
        }

        listPanel.revalidate();
        listPanel.repaint();

        revalidate();
        repaint();
    }

