    private JLabel createLabel(
            String text,
            Color color,
            boolean bold
    )
    {
        JLabel label =
                new JLabel(
                        text
                );

        label.setForeground(
                color
        );

        label.setAlignmentX(
                LEFT_ALIGNMENT
        );

        if (bold)
        {
            label.setFont(
                    label.getFont()
                            .deriveFont(
                                    Font.BOLD
                            )
            );
        }

        return label;
    }

    // ========================================================
    // STATUS
    // ========================================================

    private String friendlyStatus(
            String status
    )
    {
        if (
                ActiveFlipStore.ActiveFlip.STATUS_BUYING
                        .equals(
                                status
                        )
        )
        {
            return "Buying";
        }

        if (
                ActiveFlipStore.ActiveFlip.STATUS_READY_TO_SELL
                        .equals(
                                status
                        )
        )
        {
            return "Ready to sell";
        }

        if (
                ActiveFlipStore.ActiveFlip.STATUS_SELLING
                        .equals(
                                status
                        )
        )
        {
            return "Selling";
        }

        if (
                ActiveFlipStore.ActiveFlip.STATUS_COMPLETED
                        .equals(
                                status
                        )
        )
        {
            return "Completed";
        }

        return "Planned";
    }

    private Color statusColor(
            String status
    )
    {
        if (
                ActiveFlipStore.ActiveFlip.STATUS_READY_TO_SELL
                        .equals(
                                status
                        )
        )
        {
            return GREEN;
        }

        if (
                ActiveFlipStore.ActiveFlip.STATUS_COMPLETED
                        .equals(
                                status
                        )
        )
        {
            return GREEN;
        }

        return YELLOW;
    }

    // ========================================================
    // FORMATTING
    // ========================================================

    private String formatGp(
            long value
    )
    {
        return numberFormat.format(
                value
        )
                + " gp";
    }

    private String signedGp(
            long value
    )
    {
        if (value > 0)
        {
            return "+"
                    + formatGp(
                    value
            );
        }

        return formatGp(
                value
        );
    }
}

