    private long parseGp(
            String value
    )
    {
        if (
                value == null
                        || value.trim().isEmpty()
        )
        {
            throw new IllegalArgumentException(
                    "Fill in all fields"
            );
        }

        String cleaned =
                value
                        .trim()
                        .toLowerCase()
                        .replace(",", "")
                        .replace(" ", "")
                        .replace("_", "");

        double multiplier =
                1.0;

        if (
                cleaned.endsWith(
                        "k"
                )
        )
        {
            multiplier =
                    1_000.0;

            cleaned =
                    cleaned.substring(
                            0,
                            cleaned.length() - 1
                    );
        }
        else if (
                cleaned.endsWith(
                        "m"
                )
        )
        {
            multiplier =
                    1_000_000.0;

            cleaned =
                    cleaned.substring(
                            0,
                            cleaned.length() - 1
                    );
        }
        else if (
                cleaned.endsWith(
                        "b"
                )
        )
        {
            multiplier =
                    1_000_000_000.0;

            cleaned =
                    cleaned.substring(
                            0,
                            cleaned.length() - 1
                    );
        }

        try
        {
            double parsed =
                    Double.parseDouble(
                            cleaned
                    );

            long result =
                    Math.round(
                            parsed * multiplier
                    );

            if (result <= 0)
            {
                throw new IllegalArgumentException(
                        "Values must be above 0"
                );
            }

            return result;
        }
        catch (
                NumberFormatException exception
        )
        {
            throw new IllegalArgumentException(
                    "Use numbers like 150k or 2.5m"
            );
        }
    }

