    // ========================================================

    private Color getProfitColor(
            long profit
    )
    {
        if (profit > 0)
        {
            return GREEN;
        }

        if (profit < 0)
        {
            return RED;
        }

        return TEXT;
    }

    private String formatSignedGp(
            long value
    )
    {
        if (value > 0)
        {
            return "+"
                    + numberFormat.format(
                    value
            )
                    + " gp";
        }

        if (value < 0)
        {
            return "-"
                    + numberFormat.format(
                    Math.abs(value)
            )
                    + " gp";
        }

        return "0 gp";
    }

    private String formatTime(
            long timestamp
    )
    {
        DateTimeFormatter formatter =
                DateTimeFormatter.ofPattern(
                        "HH:mm"
                );

        return Instant
                .ofEpochSecond(
                        timestamp
                )
                .atZone(
                        ZoneId.systemDefault()
                )
                .format(
                        formatter
                );
    }
