    )
    {
        if (dataDirectory == null)
        {
            throw new IllegalArgumentException(
                    "dataDirectory must not be null"
            );
        }

        defaultDataDirectory =
                dataDirectory;

        gson =
                RuneRadarApiClient
                        .getInjectedGson()
                        .newBuilder()
                        .setPrettyPrinting()
                        .create();

        storageFile =
                dataDirectory.joinSegment(
                        "profit_history.json"
                );

        load();
    }

    private static Filepath getDefaultDataDirectory()
    {
        if (defaultDataDirectory == null)
        {
            throw new IllegalStateException(
                    "RuneRadar storage has not been initialized"
            );
        }

        return defaultDataDirectory;
    }

    // ========================================================
    // ADD FLIP
    // ========================================================

    public FlipRecord addCompletedFlip(
            String itemName,
            long buyPrice,
            long sellPrice,
            long quantity
    )
    {
        if (
                itemName == null
                        || itemName.trim().isEmpty()
        )
        {
            throw new IllegalArgumentException(
                    "Enter an item name."
            );
        }

        if (buyPrice <= 0)
        {
            throw new IllegalArgumentException(
                    "Buy price must be above 0."
            );
        }

        if (sellPrice <= 0)
        {
            throw new IllegalArgumentException(
                    "Sell price must be above 0."
            );
        }

        if (quantity <= 0)
        {
            throw new IllegalArgumentException(
                    "Quantity must be above 0."
            );
        }

        long taxPerItem =
                calculateEstimatedTaxPerItem(
                        sellPrice
                );

        long totalBoughtFor =
                safeMultiply(
                        buyPrice,
                        quantity
                );

        long totalSoldFor =
                safeMultiply(
                        sellPrice,
                        quantity
                );

        long totalTax =
                safeMultiply(
                        taxPerItem,
                        quantity
                );

        long netProfit =
                totalSoldFor
                        - totalBoughtFor
                        - totalTax;

        FlipRecord record =
                new FlipRecord(
                        Instant.now()
                                .getEpochSecond(),
                        itemName.trim(),
                        buyPrice,
                        sellPrice,
                        quantity,
                        totalTax,
                        netProfit
                );

        records.add(
                record
        );

        recordStatistics(
                record
        );

        sortNewestFirst();

        save();

        return record;
    }

    public synchronized FlipRecord addCompletedFlipExact(
            String itemName,
            long buyPrice,
            long sellPrice,
            long quantity,
            long tax,
            long netProfit
    )
    {
        if (
                itemName == null
                        || itemName.trim().isEmpty()
        )
        {
            throw new IllegalArgumentException(
                    "Enter an item name."
            );
        }

        if (buyPrice <= 0)
        {
            throw new IllegalArgumentException(
                    "Buy price must be above 0."
            );
        }

        if (sellPrice <= 0)
        {
            throw new IllegalArgumentException(
                    "Sell price must be above 0."
            );
        }

        if (quantity <= 0)
        {
            throw new IllegalArgumentException(
                    "Quantity must be above 0."
            );
        }

        FlipRecord record =
                new FlipRecord(
                        Instant.now()
                                .getEpochSecond(),
                        itemName.trim(),
                        buyPrice,
                        sellPrice,
                        quantity,
                        Math.max(
                                tax,
                                0
                        ),
                        netProfit
                );

        records.add(
                record
        );

        recordStatistics(
                record
        );

        sortNewestFirst();

        save();

        return record;
    }

    // ========================================================
    // TAX
    // ========================================================

    private long calculateEstimatedTaxPerItem(
            long sellPrice
    )
    {
        if (sellPrice <= 0)
        {
            return 0;
        }

        long tax =
                (long) Math.floor(
                        sellPrice
                                * GE_TAX_RATE
                );

        return Math.min(
                tax,
                GE_TAX_CAP_PER_ITEM
        );
    }

