    {
        return totalProfit;
    }

    public int getCompletedFlipCount()
    {
        return completedFlipCount;
    }

    // ========================================================
    // HISTORY
    // ========================================================

    public List<FlipRecord> getHistory()
    {
        return new ArrayList<>(
                records
        );
    }

    public List<FlipRecord> getRecentHistory(
            int limit
    )
    {
        int safeLimit =
                Math.max(
                        0,
                        limit
                );

        int end =
                Math.min(
                        safeLimit,
                        records.size()
                );

        return new ArrayList<>(
                records.subList(
                        0,
                        end
                )
        );
    }

    public void deleteRecord(
            long timestamp
    )
    {
        records.removeIf(
                record ->
                        record.getTimestamp()
                                == timestamp
        );

        save();
    }

    public void clearHistory()
    {
        records.clear();

        save();
    }

    public void resetStatistics()
    {
        sessionProfit = 0;
        todayProfit = 0;
        todayDate = LocalDate.now().toString();
        totalProfit = 0;
        completedFlipCount = 0;

        save();
    }

    // ========================================================
    // LOAD / SAVE
    // ========================================================

    private void load()
    {
        records.clear();

        sessionProfit = 0;
        todayProfit = 0;
        todayDate = LocalDate.now().toString();
        totalProfit = 0;
        completedFlipCount = 0;

        if (
                !storageFile.exists()
        )
        {
            return;
        }

        try (
                Reader reader =
                        storageFile.openBufferedReader()
        )
        {
            JsonElement root =
                    gson.fromJson(
                            reader,
                            JsonElement.class
                    );

            if (root == null)
            {
                return;
            }

            if (root.isJsonArray())
            {
                Type listType =
                        new TypeToken<
                                List<FlipRecord>
                                >()
                        {
                        }
                                .getType();

                List<FlipRecord> loaded =
                        gson.fromJson(
                                root,
                                listType
                        );

                if (loaded != null)
                {
                    records.addAll(
                            loaded
                    );
                }

                rebuildStatisticsFromHistory();
                save();
            }
            else
            {
                TrackerData loaded =
                        gson.fromJson(
                                root,
                                TrackerData.class
                        );

                if (
                        loaded != null
                                && loaded.records != null
                )
                {
                    records.addAll(
                            loaded.records
                    );
                }

                if (
                        loaded == null
                                || loaded.schemaVersion < 2
                )
                {
                    rebuildStatisticsFromHistory();
                }
                else
                {
                    todayProfit = loaded.todayProfit;
                    todayDate = loaded.todayDate;
                    totalProfit = loaded.totalProfit;
                    completedFlipCount = loaded.completedFlipCount;
                }
            }

            sortNewestFirst();

            rollDailyStatisticsIfNeeded();
        }
        catch (Exception ignored)
        {
        }
    }

    private void save()
    {
        try
        {
            storageFile.getParent()
                    .createDirectories();

            try (
                    Writer writer =
                            storageFile.openBufferedWriter()
            )
            {
                gson.toJson(
                        new TrackerData(
                                records,
                                todayProfit,
                                todayDate,
                                totalProfit,
                                completedFlipCount
                        ),
                        writer
                );
            }
        }
        catch (Exception ignored)
        {
        }
    }

    private void sortNewestFirst()
    {
        records.sort(
                Comparator.comparingLong(
                                FlipRecord::getTimestamp
                        )
                        .reversed()
        );
    }

    private void recordStatistics(
            FlipRecord record
    )
    {
        rollDailyStatisticsIfNeeded();

        sessionProfit += record.getNetProfit();
        todayProfit += record.getNetProfit();
        totalProfit += record.getNetProfit();
        completedFlipCount++;
    }

    private void rollDailyStatisticsIfNeeded()
    {
        String currentDate =
                LocalDate.now().toString();

        if (!currentDate.equals(todayDate))
        {
            todayDate = currentDate;
            todayProfit = 0;
        }
    }

    private void rebuildStatisticsFromHistory()
    {
        LocalDate currentDate =
                LocalDate.now();

        todayDate = currentDate.toString();
        todayProfit = 0;
        totalProfit = 0;
        completedFlipCount = records.size();

        for (FlipRecord record : records)
        {
            totalProfit += record.getNetProfit();

            LocalDate recordDate =
                    Instant.ofEpochSecond(
                                    record.getTimestamp()
                            )
                            .atZone(
                                    ZoneId.systemDefault()
                            )
                            .toLocalDate();

            if (currentDate.equals(recordDate))
            {
                todayProfit += record.getNetProfit();
            }
        }
    }

    private long safeMultiply(
            long first,
            long second
    )
    {
        try
        {
            return Math.multiplyExact(
                    first,
                    second
            );
        }
        catch (ArithmeticException exception)
        {
            throw new IllegalArgumentException(
                    "The entered values are too large."
            );
        }
    }

    private static class TrackerData
    {
        private int schemaVersion = 2;

        private List<FlipRecord> records =
                new ArrayList<>();

        private long todayProfit;

        private String todayDate;

        private long totalProfit;

        private int completedFlipCount;

        private TrackerData()
        {
        }

        private TrackerData(
                List<FlipRecord> records,
                long todayProfit,
                String todayDate,
                long totalProfit,
                int completedFlipCount
        )
        {
            this.records = new ArrayList<>(records);
            this.todayProfit = todayProfit;
            this.todayDate = todayDate;
            this.totalProfit = totalProfit;
            this.completedFlipCount = completedFlipCount;
        }
    }

