    private static String cleanHeaderValue(
            String value
    )
    {
        if (value == null)
        {
            return "";
        }

        return value
                .trim()
                .replace(
                        "\r",
                        ""
                )
                .replace(
                        "\n",
                        ""
                );
    }

    private static Request.Builder createRequestBuilder(
            String urlText
    )
    {
        Request.Builder builder =
                new Request.Builder()
                        .url(
                                urlText
                        )
                        .get()
                        .header(
                                "Accept",
                                "application/json"
                        );

        if (!installId.isEmpty())
        {
            builder.header(
                    "X-RuneRadar-Install-ID",
                    installId
            );
        }

        if (!pluginVersion.isEmpty())
        {
            builder.header(
                    "X-RuneRadar-Version",
                    pluginVersion
            );
        }

        if (!sessionToken.isEmpty())
        {
            builder.header(
                    "Authorization",
                    "Bearer " + sessionToken
            );
        }

        return builder;
    }

