    private ApiResponse requestRecommendations(
            String endpoint,
            long cashStack,
            String flipType,
            int limit
    ) throws Exception
    {
        String cleanedFlipType =
                flipType == null
                        ? "FAST"
                        : flipType
                        .trim()
                        .toUpperCase()
                        .replace(
                                " ",
                                "_"
                        );

        String urlText =
                API_BASE_URL
                        + endpoint
                        + "?cash=" + cashStack
                        + "&type=" + cleanedFlipType
                        + "&limit=" + limit;

        Request request =
                createRequestBuilder(
                        urlText
                ).build();

        String responseText;

        try (
                Response response =
                        getInjectedHttpClient()
                                .newCall(
                                        request
                                )
                                .execute()
        )
        {
            if (!response.isSuccessful())
            {
                throw createApiException(
                        response
                );
            }

            ResponseBody responseBody =
                    response.body();

            if (responseBody == null)
            {
                throw new RuntimeException(
                        "RuneRadar API returned no response body."
                );
            }

            responseText =
                    responseBody.string();
        }

        ApiResponse response =
                getInjectedGson().fromJson(
                        responseText,
                        ApiResponse.class
                );

        if (
                response == null
        )
        {
            throw new RuntimeException(
                    "RuneRadar API returned no data."
            );
        }

        if (
                response.recommendations
                        == null
        )
        {
            response.recommendations =
                    Collections.emptyList();
        }

        return response;
    }

    private static RuntimeException createApiException(
            Response response
    )
    {
        String code =
                "HTTP_" + response.code();

        String message =
                "RuneRadar API returned HTTP "
                        + response.code();

        ResponseBody responseBody =
                response.body();

        if (responseBody != null)
        {
            try
            {
                ApiErrorResponse apiError =
                        getInjectedGson().fromJson(
                                responseBody.string(),
                                ApiErrorResponse.class
                        );

                if (
                        apiError != null
                                && apiError.message != null
                                && !apiError.message.trim().isEmpty()
                )
                {
                    message = apiError.message.trim();
                }

                if (
                        apiError != null
                                && apiError.code != null
                                && !apiError.code.trim().isEmpty()
                )
                {
                    code = apiError.code.trim();
                }
            }
            catch (Exception ignored)
            {
            }
        }

        return new ApiException(
                response.code(),
                code,
                message
        );
    }

