    private String getPersistedValue(
            String key,
            String fallback
    )
    {
        if (configManager == null)
        {
            return fallback;
        }

        String value = configManager.getConfiguration(
                CONFIG_GROUP,
                key
        );

        if (
                value == null
                        || value.trim().isEmpty()
        )
        {
            return fallback;
        }

        return value.trim();
    }

    private String loadPersistedChoice(
            String key,
            String fallback,
            String... allowedValues
    )
    {
        String value = getPersistedValue(
                key,
                fallback
        ).toUpperCase();

        for (String allowedValue : allowedValues)
        {
            if (allowedValue.equals(value))
            {
                return value;
            }
        }

        return fallback;
    }

    private void persistSetting(
            String key,
            Object value
    )
    {
        if (configManager != null)
        {
            configManager.setConfiguration(
                    CONFIG_GROUP,
                    key,
                    value
            );
        }
    }

    private String getOrCreateDeviceId()
    {
        String savedDeviceId =
                getPersistedValue(
                        AUTH_DEVICE_ID_KEY,
                        ""
                );

        if (!savedDeviceId.isEmpty())
        {
            return savedDeviceId;
        }

        String newDeviceId =
                UUID.randomUUID().toString();

        persistSetting(
                AUTH_DEVICE_ID_KEY,
                newDeviceId
        );

        return newDeviceId;
    }

    private void saveSessionToken(
            String token
    )
    {
        sessionToken =
                token == null
                        ? ""
                        : token.trim();

        RuneRadarApiClient.setSessionToken(
                sessionToken
        );

        if (configManager != null)
        {
            if (sessionToken.isEmpty())
            {
                configManager.unsetConfiguration(
                        CONFIG_GROUP,
                        AUTH_SESSION_TOKEN_KEY
                );
            }
            else
            {
                persistSetting(
                        AUTH_SESSION_TOKEN_KEY,
                        sessionToken
                );
            }
        }
    }

