    @Override
    public void addNotify()
    {
        super.addNotify();

        if (!autoRefreshTimer.isRunning())
        {
            autoRefreshTimer.start();
        }

        if (!freshnessTimer.isRunning())
        {
            freshnessTimer.start();
        }
    }

    @Override
    public void removeNotify()
    {
        autoRefreshTimer.stop();

        freshnessTimer.stop();

        super.removeNotify();
    }

    public void stop()
    {
        autoRefreshTimer.stop();
        freshnessTimer.stop();
        requestNumber++;
    }

