    private void applyCashStack()
    {
        try
        {
            currentCashStack =
                    parseCashStack(
                            cashInput
                                    .getText()
                                    .trim()
                    );

            cashInput.setText(
                    friendlyCashInput(
                            currentCashStack
                    )
            );

            updateCashLabel();

            if (configManager != null)
            {
                configManager.setConfiguration(
                        "runeradar",
                        "cashStack",
                        currentCashStack
                );
            }

            currentIndex = 0;

            loadRecommendations(
                    false,
                    false
            );

            restartAutoRefreshTimer();
        }
        catch (
                IllegalArgumentException exception
        )
        {
            statusLabel.setForeground(
                    RED
            );

            statusLabel.setText(
                    exception.getMessage()
            );
        }
    }

    private long parseCashStack(
            String value
    )
    {
        if (
                value == null
                        || value.trim().isEmpty()
        )
        {
            throw new IllegalArgumentException(
                    "Enter your cash stack"
            );
        }

        String cleaned =
                value
                        .toLowerCase()
                        .replace(",", "")
                        .replace(" ", "")
                        .replace("_", "");

        BigDecimal multiplier =
                BigDecimal.ONE;

        if (cleaned.endsWith("k"))
        {
            multiplier =
                    BigDecimal.valueOf(
                            1_000L
                    );

            cleaned =
                    cleaned.substring(
                            0,
                            cleaned.length() - 1
                    );
        }
        else if (cleaned.endsWith("m"))
        {
            multiplier =
                    BigDecimal.valueOf(
                            1_000_000L
                    );

            cleaned =
                    cleaned.substring(
                            0,
                            cleaned.length() - 1
                    );
        }
        else if (cleaned.endsWith("b"))
        {
            multiplier =
                    BigDecimal.valueOf(
                            1_000_000_000L
                    );

            cleaned =
                    cleaned.substring(
                            0,
                            cleaned.length() - 1
                    );
        }

        try
        {
            long cash =
                    new BigDecimal(
                            cleaned
                    )
                            .multiply(
                                    multiplier
                            )
                            .longValueExact();

            if (cash < 0)
            {
                throw new IllegalArgumentException(
                        "Cash stack cannot be below 0"
                );
            }

            if (cash > MAX_CASH_STACK)
            {
                throw new IllegalArgumentException(
                        "Maximum cash stack is 2.147B"
                );
            }

            return cash;
        }
        catch (
                ArithmeticException
                | NumberFormatException exception
        )
        {
            throw new IllegalArgumentException(
                    "Use for example: 25m, 500k or 100m"
            );
        }
    }

    private String friendlyCashInput(
            long cash
    )
    {
        if (
                cash >= 1_000_000_000L
                        && cash % 1_000_000_000L == 0
        )
        {
            return
                    (cash / 1_000_000_000L)
                            + "b";
        }

        if (
                cash >= 1_000_000L
                        && cash % 1_000_000L == 0
        )
        {
            return
                    (cash / 1_000_000L)
                            + "m";
        }

        if (
                cash >= 1_000L
                        && cash % 1_000L == 0
        )
        {
            return
                    (cash / 1_000L)
                            + "k";
        }

        return Long.toString(
                cash
        );
    }

