    private void updateSortSelector()
    {
        String displayValue;

        switch (currentSortMode)
        {
            case "PROFIT":
                displayValue = "Profit";
                break;

            case "ROI":
                displayValue = "ROI";
                break;

            case "SCORE":
                displayValue = "Score";
                break;

            case "VOLUME":
                displayValue = "Volume";
                break;

            default:
                displayValue = "Default ranking";
                break;
        }

        sortSelector.setSelectedItem(
                displayValue
        );
    }

    private void setSortModeFromSelector()
    {
        Object selected =
                sortSelector.getSelectedItem();

        String selectedText =
                selected == null
                        ? "Default ranking"
                        : selected.toString();

        switch (selectedText)
        {
            case "Profit":
                currentSortMode = "PROFIT";
                break;

            case "ROI":
                currentSortMode = "ROI";
                break;

            case "Score":
                currentSortMode = "SCORE";
                break;

            case "Volume":
                currentSortMode = "VOLUME";
                break;

            default:
                currentSortMode = "DEFAULT";
                break;
        }

        persistSetting(
                SORT_MODE_KEY,
                currentSortMode
        );

        applyRecommendationSort();

        currentIndex = 0;

        showCurrentFlip();
    }

    private void applyRecommendationSort()
    {
        recommendations =
                new ArrayList<>(
                        defaultRecommendations
                );

        Comparator<RuneRadarApiClient.Recommendation> comparator = null;

        switch (currentSortMode)
        {
            case "PROFIT":
                comparator = Comparator.comparingLong(
                        RuneRadarApiClient.Recommendation::getNetExpectedProfit
                );
                break;

            case "ROI":
                comparator = Comparator.comparingDouble(
                        RuneRadarApiClient.Recommendation::getRoi
                );
                break;

            case "SCORE":
                comparator = Comparator.comparingInt(
                        RuneRadarApiClient.Recommendation::getScore
                );
                break;

            case "VOLUME":
                comparator = Comparator.comparingLong(
                        RuneRadarApiClient.Recommendation::getVolume
                );
                break;

            default:
                break;
        }

        if (comparator != null)
        {
            recommendations.sort(
                    comparator.reversed()
            );
        }
    }

