    private void startCurrentFlip()
    {
        if (
                recommendations.isEmpty()
                        || currentIndex < 0
                        || currentIndex >= recommendations.size()
        )
        {
            return;
        }

        RuneRadarApiClient.Recommendation item =
                recommendations.get(
                        currentIndex
                );

        if (hasActiveFlipForItem(item.getId()))
        {
            updateStartActiveFlipButton();

            return;
        }

        activeFlipStore.addRecommendation(
                item.getId(),
                item.getName(),
                item.getBuy(),
                item.getSell(),
                Math.toIntExact(
                        item.getRecommendedQty()
                ),
                item.getNetExpectedProfit(),
                getTrackingCategoryForRecommendation(
                        item
                )
        );

        activeFlipsPanel.refresh();

        updateStartActiveFlipButton();

        updatedLabel.setText(
                "Added to Active Flips • NET target after GE tax"
        );

        revalidate();

        repaint();
    }

    public String getTrackingCategoryForRecommendation(
            RuneRadarApiClient.Recommendation recommendation
    )
    {
        if (
                "HIGH_PROFIT".equals(
                        currentFlipType
                )
        )
        {
            return "HIGH_PROFIT";
        }

        if (recommendation != null)
        {
            String tradingSpeed =
                    recommendation.getTradingSpeed();

            if (tradingSpeed != null)
            {
                String cleaned =
                        tradingSpeed
                                .trim()
                                .toUpperCase();

                if (
                        "FAST".equals(
                                cleaned
                        )
                                || "BALANCED".equals(
                                cleaned
                        )
                                || "SLOW".equals(
                                cleaned
                        )
                )
                {
                    return cleaned;
                }
            }
        }

        return "BALANCED";
    }

    private boolean hasActiveFlipForItem(
            int itemId
    )
    {
        for (
                ActiveFlipStore.ActiveFlip flip
                : activeFlipStore.getAll()
        )
        {
            if (
                    flip != null
                            && !flip.isCompleted()
                            && flip.getItemId() == itemId
            )
            {
                return true;
            }
        }

        return false;
    }

    private void updateStartActiveFlipButton()
    {
        if (
                recommendations.isEmpty()
                        || currentIndex < 0
                        || currentIndex >= recommendations.size()
        )
        {
            startActiveFlipButton.setText(
                    "Start Active Flip"
            );

            startActiveFlipButton.setEnabled(
                    false
            );

            return;
        }

        RuneRadarApiClient.Recommendation item =
                recommendations.get(
                        currentIndex
                );

        boolean alreadyActive =
                hasActiveFlipForItem(
                        item.getId()
                );

        startActiveFlipButton.setText(
                alreadyActive
                        ? "Already Active"
                        : "Start Active Flip"
        );

        startActiveFlipButton.setEnabled(
                !blockingLoad
                        && !alreadyActive
        );
    }

    // ========================================================
    // API LOADING
    // ========================================================

    private void loadRecommendations(
            boolean preserveSelection,
            boolean quietRefresh
    )
    {
        final int thisRequest =
                ++requestNumber;

        final Integer selectedItemId =
                getSelectedItemId();

        final String selectedItemName =
                getSelectedItemName();

        requestInProgress =
                true;

        blockingLoad =
                !quietRefresh;

        lastRefreshFailed =
                false;

        updateResultModeButtons();

        updateFlipTypeButtons();

        updateNavigationButtons();

        applyCashButton.setEnabled(
                !blockingLoad
        );

        refreshButton.setEnabled(
                false
        );

        sortSelector.setEnabled(
                !blockingLoad
        );

        if (quietRefresh)
        {
            updatedLabel.setText(
                    "Refreshing market data..."
            );

            statusLabel.setForeground(
                    GOLD
            );

            statusLabel.setText(
                    "Loading latest recommendations..."
            );
        }
        else
        {
            setLoadingState();
        }

        final long cashStack =
                currentCashStack == 0
                        ? MAX_CASH_STACK
                        : currentCashStack;

        final String requestedFlipType =
                currentFlipType;

        final String requestedResultMode =
                currentResultMode;

        Thread thread =
                new Thread(
                        () ->
                        {
                            try
                            {
                                RuneRadarApiClient.ApiResponse response;

                                if (
                                        requestedResultMode.equals(
                                                "MORE"
                                        )
                                )
                                {
                                    response =
                                            apiClient.getMoreOpportunities(
                                                    cashStack,
                                                    requestedFlipType,
                                                    MAX_RESULT_LIMIT
                                            );
                                }
                                else
                                {
                                    response =
                                            apiClient.getRecommendations(
                                                    cashStack,
                                                    requestedFlipType,
                                                    MAX_RESULT_LIMIT
                                            );
                                }

                                SwingUtilities.invokeLater(
                                        () ->
                                        {
                                            if (
                                                    thisRequest
                                                            != requestNumber
                                            )
                                            {
                                                return;
                                            }

                                            if (
                                                    response.getPlan() != null
                                                            && !response.getPlan().trim().isEmpty()
                                                            && !response.getPlan().equalsIgnoreCase(
                                                            accountPlan
                                                    )
                                            )
                                            {
                                                accountPlan =
                                                        response.getPlan();
                                                resetFreeOnlySelections();
                                                renderAccountContent();
                                            }

                                            defaultRecommendations =
                                                    new ArrayList<>(
                                                            response.getRecommendations()
                                                    );

                                            applyRecommendationSort();

                                            updatedAt =
                                                    response.getUpdatedAt();

                                            requestInProgress =
                                                    false;

                                            blockingLoad =
                                                    false;

                                            lastRefreshFailed =
                                                    false;

                                            applyCashButton.setEnabled(
                                                    true
                                            );

                                            refreshButton.setEnabled(
                                                    true
                                            );

                                            sortSelector.setEnabled(
                                                    true
                                            );

                                            updateResultModeButtons();

                                            updateFlipTypeButtons();

                                            if (preserveSelection)
                                            {
                                                restoreSelection(
                                                        selectedItemId,
                                                        selectedItemName
                                                );
                                            }
                                            else
                                            {
                                                currentIndex = 0;
                                            }

                                            showCurrentFlip();

                                            if (!sessionToken.isEmpty())
                                            {
                                                refreshAccount(true);
                                            }
                                        }
                                );
                            }
                            catch (
                                    Exception exception
                            )
                            {
                                SwingUtilities.invokeLater(
                                        () ->
                                        {
                                            if (
                                                    thisRequest
                                                            != requestNumber
                                            )
                                            {
                                                return;
                                            }

                                            requestInProgress =
                                                    false;

                                            blockingLoad =
                                                    false;

                                            applyCashButton.setEnabled(
                                                    true
                                            );

                                            refreshButton.setEnabled(
                                                    true
                                            );

                                            sortSelector.setEnabled(
                                                    true
                                            );

                                            updateResultModeButtons();

                                            updateFlipTypeButtons();

                                            if (
                                                    recommendations.isEmpty()
                                            )
                                            {
                                                showInitialApiError(
                                                        exception.getMessage()
                                                );
                                            }
                                            else
                                            {
                                                lastRefreshFailed =
                                                        true;

                                                showCurrentFlip();

                                                statusLabel.setForeground(
                                                        RED
                                                );

                                                statusLabel.setText(
                                                        friendlyApiError(
                                                                exception.getMessage(),
                                                                true
                                                        )
                                                );
                                            }
                                        }
                                );
                            }
                        }
                );

        thread.setName(
                "RuneRadar-API"
        );

        thread.setDaemon(
                true
        );

        thread.start();
    }

