    private void restoreSelection(
            Integer itemId,
            String itemName
    )
    {
        if (recommendations.isEmpty())
        {
            currentIndex = 0;

            return;
        }

        if (itemId != null)
        {
            for (
                    int index = 0;
                    index < recommendations.size();
                    index++
            )
            {
                if (
                        recommendations
                                .get(index)
                                .getId()
                                == itemId
                )
                {
                    currentIndex =
                            index;

                    return;
                }
            }
        }

        if (itemName != null)
        {
            for (
                    int index = 0;
                    index < recommendations.size();
                    index++
            )
            {
                if (
                        itemName.equalsIgnoreCase(
                                recommendations
                                        .get(index)
                                        .getName()
                        )
                )
                {
                    currentIndex =
                            index;

                    return;
                }
            }
        }

        currentIndex = 0;
    }

