    private String friendlyApiError(
            String message,
            boolean keepingPreviousData
    )
    {
        String cleaned =
                message == null
                        ? ""
                        : message.trim();

        if (cleaned.toLowerCase().contains("runeradar pro"))
        {
            return cleaned;
        }

        if (keepingPreviousData)
        {
            return "Refresh failed • showing last valid data";
        }

        return "Could not load recommendations • check your connection and retry";
    }

    // ========================================================
    // NAVIGATION
    // ========================================================

    private void updateNavigationButtons()
    {
        boolean multipleResults =
                !blockingLoad
                        && recommendations.size() > 1;

        previousButton.setEnabled(
                multipleResults
        );

        nextButton.setEnabled(
                multipleResults
        );
    }

    private void previousFlip()
    {
        if (
                blockingLoad
                        || recommendations.size() <= 1
        )
        {
            return;
        }

        currentIndex--;

        if (currentIndex < 0)
        {
            currentIndex =
                    recommendations.size()
                            - 1;
        }

        showCurrentFlip();
    }

    private void nextFlip()
    {
        if (
                blockingLoad
                        || recommendations.size() <= 1
        )
        {
            return;
        }

        currentIndex++;

        if (
                currentIndex
                        >= recommendations.size()
        )
        {
            currentIndex = 0;
        }

        showCurrentFlip();
    }

    // ========================================================
    // AUTO REFRESH
    // ========================================================

    private void restartAutoRefreshTimer()
    {
        autoRefreshTimer.restart();
    }

    // ========================================================
    // FORMATTING
    // ========================================================

    private String formatGp(
            long amount
    )
    {
        return numberFormat.format(
                amount
        ) + " gp";
    }

    private String safeText(
            String value
    )
    {
        if (
                value == null
                        || value.trim().isEmpty()
        )
        {
            return "-";
        }

        return value;
    }

    private String friendlyTradingSpeed(
            String value
    )
    {
        if (value == null)
        {
            return "-";
        }

        if (
                value.equalsIgnoreCase(
                        "FAST"
                )
        )
        {
            return "FAST";
        }

        if (
                value.equalsIgnoreCase(
                        "BALANCED"
                )
        )
        {
            return "BALANCED";
        }

        if (
                value.equalsIgnoreCase(
                        "SLOW"
                )
        )
        {
            return "SLOW";
        }

        return value;
    }

    private String friendlyStability(
            String value
    )
    {
        if (value == null)
        {
            return "-";
        }

        if (
                value.equalsIgnoreCase(
                        "STABLE"
                )
        )
        {
            return "GOOD";
        }

        if (
                value.equalsIgnoreCase(
                        "OK"
                )
        )
        {
            return "OK";
        }

        return "POOR";
    }

    private long secondsAgo()
    {
        if (updatedAt <= 0)
        {
            return 0;
        }

        long now =
                Instant.now()
                        .getEpochSecond();

        return Math.max(
                0,
                now - updatedAt
        );
    }
}

