        private BufferedImage createTemporaryIcon()
        {
                int size =
                        16;

                BufferedImage image =
                        new BufferedImage(
                                size,
                                size,
                                BufferedImage.TYPE_INT_ARGB
                        );

                Graphics2D graphics =
                        image.createGraphics();

                graphics.setRenderingHint(
                        RenderingHints.KEY_ANTIALIASING,
                        RenderingHints.VALUE_ANTIALIAS_ON
                );

                graphics.setColor(
                        new Color(
                                32,
                                120,
                                110
                        )
                );

                graphics.fillOval(
                        1,
                        1,
                        14,
                        14
                );

                graphics.setColor(
                        new Color(
