        private String getOrCreateInstallId()
        {
                String installId =
                        configManager.getConfiguration(
                                CONFIG_GROUP,
                                INSTALL_ID_KEY
                        );

                if (installId != null)
                {
                        installId =
                                installId.trim();
                }

                if (
                        installId != null
                                && !installId.isEmpty()
                )
                {
                        return installId;
                }

                installId =
                        UUID.randomUUID()
                                .toString();

                configManager.setConfiguration(
                        CONFIG_GROUP,
                        INSTALL_ID_KEY,
                        installId
                );

                return installId;
        }

